    sampleSolution: "SELECT p1.name as product_1, p2.name as product_2, c.name as category, ABS(p1.price - p2.price) as price_diff FROM products p1 JOIN products p2 ON p1.category_id = p2.category_id AND p1.id < p2.id JOIN categories c ON p1.category_id = c.id WHERE ABS(p1.price - p2.price) > 10000 ORDER BY price_diff DESC;",
