    hint: 'countIf(condition) считает строки по условию. avgIf(expr, condition) считает среднее по условию. Условия могут ссылаться на разные столбцы.',
    sampleSolution: "SELECT c.name AS category, countIf(r.rating >= 4) AS good_reviews, ROUND(avgIf(r.rating, r.rating > 0), 2) AS avg_rating FROM categories c JOIN products p ON c.id = p.category_id JOIN reviews r ON p.id = r.product_id GROUP BY c.name ORDER BY avg_rating DESC;",
