    sampleSolution: "WITH order_with_prev AS (SELECT o.customer_id, o.order_date, o.total_amount, LAG(o.total_amount) OVER (PARTITION BY o.customer_id ORDER BY o.order_date) as prev_amount, ROW_NUMBER() OVER (PARTITION BY o.customer_id ORDER BY o.order_date DESC) as rn FROM orders o) SELECT c.first_name, c.last_name, op.prev_amount as prev_order, op.total_amount as last_order, op.total_amount - op.prev_amount as diff FROM order_with_prev op JOIN customers c ON op.customer_id = c.id WHERE op.rn = 1 AND op.prev_amount IS NOT NULL AND op.total_amount > op.prev_amount ORDER BY diff DESC;",
